INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210319, 101189, '8980bdc4-cf9c-5366-a25f-30c4e4ae5a24', 210318, 'Strongly disagree. A chemistry TA grades papers for the department''s benefit; a point guard generates TV revenue for the athletic department''s benefit. Both are workers producing value for the institution. The distinction is snobbery.', 'strongly_disagree', 5, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210322, 101193, '7062708e-18b3-5d30-bc74-2c1d48b23543', 210321, 'My father had his cardiac episode the Monday after a spring forward, and his doctor mentioned the pattern unprompted. Anecdote is not data, but the data backs the anecdote here.', 'agree', 8, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210324, 101196, 'e5cd8450-ec25-5d34-8abc-fbf7a62ce129', 210323, 'I feel both sides. Dark winter mornings with kids at bus stops genuinely scare me, but losing summer evenings would hurt too. Maybe the real lesson is that any fixed time makes someone unhappy.', 'neutral', 2, '2026-09-24 12:54:25+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210329, 101195, 'd671fe27-a9c4-5bd7-b0ae-04e87cff34ae', 210328, 'Strongly disagree that this justifies national policy. A payroll software bug is an IT problem, not a reason to reorder time for 330 million people. Fix the software.', 'strongly_disagree', 3, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210330, 101197, '28e4f2ca-643f-5283-bf20-324b8371ae73', 210326, 'The temperature objection does not hold up. The studies compare the same weeks across years with and without the shift, which controls for season. Evening light and street safety is a real effect.', 'disagree', 7, '2026-09-24 14:05:00+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210332, 101199, '83b1ec98-9ff0-5c5e-aa12-e20561952703', 210331, 'And small companies are the least likely to have real privacy counsel. An automatic audit forces them to build proper data practices from the start instead of treating compliance as something only giants do.', 'agree', 5, '2026-09-23 23:08:28+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210334, 101200, '32d319a3-8952-564b-85ec-3c03f956e1d3', 210333, 'Shortages get solved by demand. A guaranteed market for independent auditors would train and certify thousands of them within a few years. That is how every compliance industry was born.', 'disagree', 4, '2026-09-23 23:25:34+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210337, 101200, 'b390a614-8081-5bc6-9cf0-df5c9b0c5eb1', 210336, 'An outright ban sounds clean but would kill legitimate uses like fraud detection and emergency services. Audits at least distinguish good handling from bad, which a blanket ban never does.', 'disagree', 5, '2026-09-23 20:48:34+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210338, 101199, '9c8d1b75-7cb3-5bd9-8763-b4e02517c298', 210335, 'That is the core tension. Deterrence works if companies believe the audit is real, and belief requires public findings. Publish the results and the checkbox problem shrinks.', 'neutral', 8, '2026-09-23 23:24:28+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210340, 101201, '49778c11-6803-5c54-b317-c000fc8ab49a', 210339, 'The aviation analogy is apt. Nobody argues each country should have voluntary airplane safety. We agreed on a floor because crashes cross borders, and AI failures will too.', 'agree', 7, '2026-09-24 04:45:40+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210342, 101202, '674378e4-21e4-53ab-b8cb-18f19d173808', 210341, 'Climate accords are actually the counterpoint though. Weak global agreements still created the framework that later got strengthened. A floor that rises over time beats no floor at all.', 'neutral', 8, '2026-09-23 18:30:35+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210345, 101202, '47b274f0-edf9-5e44-a7ad-1db2a084e22e', 210344, 'The WTO and ICAO suggest it is not impossible in principle. The problem is political will on tech specifically, not some law of nature. Dismissing the whole idea concedes the field to the least responsible actors.', 'disagree', 5, '2026-09-23 21:47:35+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210346, 101201, '66b4fe36-33d2-56f0-ba09-7dbfca0fe67f', 210343, 'Sequencing sounds nice but ''later'' never comes without a deadline. Norms harden into law only when someone forces the issue, which is exactly what enforceability does.', 'disagree', 1, '2026-09-24 03:33:40+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210348, 101203, '839d2e94-4146-5ea3-9258-858df8438a08', 210347, 'The MCG final proved the demand is real when the stage matches the moment. 86,174 people did not show up by accident. Imagine what consistent prime-time treatment would build over five years.', 'agree', 3, '2026-09-24 02:04:08+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210350, 101204, '29adc068-c28d-5c6d-bc4e-5c34f94bfc81', 210349, 'Contracts get renegotiated constantly as markets shift, and rising women''s audiences are exactly the kind of shift that gets priced into the next deal. The legal chaos is overstated.', 'disagree', 5, '2026-09-23 17:25:54+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210353, 101204, '168ae641-fa10-5616-8a9e-e43c721012c8', 210352, 'The ''earn it'' framing ignores that the men''s game got a century of free promotion to build its audience. Nobody asked men''s cricket to earn its slot from zero. Equal treatment now just levels a tilted field.', 'disagree', 5, '2026-09-23 17:26:54+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210354, 101203, '32fc1aa6-a98f-5dbe-a1d7-18312d827add', 210351, 'Sponsor pressure is an interesting middle path. A few big brands demanding prime-time women''s inventory in their media buys could move broadcasters faster than any rule.', 'agree', 0, '2026-09-24 01:15:08+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210356, 101205, '52a46b83-4565-5129-a637-fd419d63dca9', 210355, 'And the pipeline argument works in both directions. Today''s casual participant is tomorrow''s volunteer coach and next decade''s Olympian parent. Participation funding is elite funding with a longer time horizon.', 'agree', 3, '2026-09-23 20:14:55+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210358, 101206, '929d6001-9546-557e-b22c-bec6bda03720', 210357, 'Separate streams make sense in theory, but in practice the grassroots stream is always the first cut in a budget crisis. Tying some elite money to participation might be the only way the grassroots survives.', 'neutral', 5, '2026-09-23 19:03:59+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210361, 101206, 'ee7943b4-bcd5-5197-8301-9a00258a076d', 210360, 'Missions can stay distinct while sharing a funding formula. Nobody is asking the Olympic trials to be a fun run. The question is whether a funding system can value both outcomes without corrupting either.', 'disagree', 4, '2026-09-23 20:49:59+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210362, 101205, '148f135c-8408-5c37-932b-78bc0fdd1875', 210359, 'The selection effect is a fair critique of the health math. But even if the savings are smaller than claimed, the direction is right, and public money should face some accounting of its public return.', 'neutral', 5, '2026-09-23 21:47:55+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210364, 101207, 'eb698a17-317e-5781-bd44-01391811b310', 210363, 'And it ends the annual circus of negotiating each record''s worth in public. Athletes know the deal, accountants know the cost, and everyone can focus on the sport instead of the press release.', 'agree', 7, '2026-09-23 18:01:25+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210366, 101208, '0ee17e88-9403-554a-b79a-f2caf7e743d8', 210365, 'Tennis is the exception, not the rule, and building policy around the exception is how you stall progress everywhere else. Most federations have a clear revenue gap running one direction.', 'disagree', 4, '2026-09-24 08:03:01+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210369, 101208, '4d826e95-fcf0-5774-bc28-4bf34075f2c3', 210368, 'Bureaucracy is also what guarantees the check arrives. Discretionary bonuses have a long history of shrinking whenever budgets tighten, and they never shrink equally.', 'disagree', 6, '2026-09-24 07:36:01+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210370, 101207, 'ab8bc4ff-6bea-5630-a52e-58de4e2a77f2', 210367, 'Maybe the compromise is standardized minimums with room above. A floor that guarantees equal treatment, plus discretion for genuinely exceptional commercial cases. Floors are easier to defend than ceilings.', 'neutral', 8, '2026-09-23 17:31:25+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210372, 101209, '06ce25a4-efd8-5581-88f7-c154d4c5c6b6', 210371, 'The nuclear analogy holds up well here. Inspectors never see inside every centrifuge either; they verify material flows at chokepoints. Compute is AI''s chokepoint, and it is even more concentrated.', 'agree', 2, '2026-09-23 21:04:25+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210374, 101210, '68507eec-bbd6-5bb8-9613-7cb6e1b560c0', 210373, 'That assumes static institutions. The IAEA started weak too and gained authority as norms solidified. Starting imperfect does not mean staying toothless forever.', 'disagree', 5, '2026-09-23 17:50:19+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210377, 101210, '5cc4b204-79e4-5048-a93e-99b939558d44', 210376, 'Distributed research is great until a lab somewhere trains something dangerous with no oversight at all. The question is not whether centralization has risks, but whether zero coordination is worse.', 'disagree', 5, '2026-09-23 15:43:19+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.comments (id, case_id, author_id, parent_id, body, stance, score, created_at) VALUES (210378, 101209, 'c42de967-cec8-5e1a-a097-c28408dbe53d', 210375, 'The surveillance objection applies to every arms-control regime ever negotiated, and we still negotiated them. Verification is always intrusive; that is what makes it verification.', 'agree', 4, '2026-09-23 18:43:25+00') ON CONFLICT (id) DO UPDATE SET case_id=EXCLUDED.case_id, author_id=EXCLUDED.author_id, parent_id=EXCLUDED.parent_id, body=EXCLUDED.body, stance=EXCLUDED.stance, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
